class Solution {
public:
    int subarraysDivByK(vector<int>& nums, int k) {
        map<int, int> seen;
        seen[0] = 1;
        int rem = 0, count = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            rem = ((rem + nums[i]) % k + k) % k;
            count += seen[rem];
            seen[rem]++;
        }
        return count;
    }
};
